 * What the page's current step card offers, compactly.
 *
 * A `rollTable` step is a single button here, exactly as on the page: the
 * roll itself, the pad, "Roll for me", the table toggle, is what the game
 * is then waiting on, covered by reusing `RequestPanel` rather than a second
 * copy of it.
 */
function RemoteStep({ pack, run, state, active }: { pack: Pack; run: ReturnType<typeof useRun>; state: RunState; active: ActiveStep }) {
  const { phase, step, index } = active;
  const [declared, setDeclared] = useState("");
  const key = `${phase.id}#${index}`;
  const ticked = useMemo(() => ticksFor(state, key), [state, key]);
  const tick = (keys: string[], on: boolean, tally?: string) => run.check(key, keys, on, tally);

  switch (step.kind) {
    case "rollTable": {
      const table = pack.tables[step.table];
      return (
        <PipSection title={phase.label}>
          <button
            className="primary big"
            onClick={() =>
              run.begin({
                kind: "table",
                tableId: step.table,
                keyPrefix: `u${state.unit}:${key}`,
                label: table?.title ?? step.table,
                completes: { phase, index },
              })
            }
          >
            {table?.title ?? "Roll"}
          </button>
        </PipSection>
      );
    }

    case "declareSubject": {
      const constraints = constraintLines(pack, state, step.constrainedBy);
      const suggested = subjectSuggestions(pack, state, step.constrainedBy);
      return (
        <PipSection title={step.label ?? `Declare the ${pack.vocabulary.subject.one}`}>
          <Constraints lines={constraints} />
          {suggested.length > 0 && (
            <div className="padRow">
              {suggested.map((name) => (
                <button key={name} className="ghost tiny" onClick={() => run.declareSubject(phase, index, name)}>
                  {name}
                </button>
              ))}
            </div>
          )}
          <div className="padRow">
            <input
              className="textInput"
              placeholder={`What is this ${pack.vocabulary.subject.one.toLowerCase()}?`}
              value={declared}
              onChange={(e) => setDeclared(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && declared && run.declareSubject(phase, index, declared)}
            />
            <button className="primary" disabled={!declared} onClick={() => run.declareSubject(phase, index, declared)}>
              Declare
            </button>
          </div>
        </PipSection>
      );
    }

    case "manual": {
      if (closesUnit(step)) return <RemoteClosing pack={pack} run={run} state={state} active={active} ticked={ticked} tick={tick} />;
      const list = step.checklist ?? [];
      const done = checklistDone(list, pack, state, ticked);
      const constraints = constraintLines(pack, state, step.constrainedBy);
      return (
        <PipSection title={step.label}>
          <Constraints lines={constraints} />
          {list.length > 0 && <Checklist items={list} pack={pack} state={state} ticked={ticked} onToggle={tick} />}
          <button className="primary big" onClick={(e) => (done ? run.completeStep(phase, index) : nudgeFirstUnticked(e.currentTarget))}>
            {done ? "Done" : "Tick what you honored"}
          </button>
        </PipSection>
      );
    }

    case "actions":
      return (
        <PipSection title={phase.label}>
          <button
            className="primary big"
            onClick={() =>
              run.begin({
                kind: "actions",
                actions: step.do,
                keyPrefix: `u${state.unit}:${key}`,
                label: phase.label,
                completes: { phase, index },
              })
            }
          >
            Continue
          </button>
        </PipSection>
      );

    case "finalizeUnit":
      return <RemoteClosing pack={pack} run={run} state={state} active={active} ticked={ticked} tick={tick} />;
  }
}

/** The closing step on the remote: the honor check, then Next or Finish, the same fork the page offers. */
function RemoteClosing({
  pack,
  run,
  state,
  active,
  ticked,
  tick,
}: {
  pack: Pack;
  run: ReturnType<typeof useRun>;
  state: RunState;
  active: ActiveStep;
  ticked: Set<string>;
  tick: (keys: string[], on: boolean, tally?: string) => void;
}) {
  const { phase, step, index } = active;
  const points = step.kind === "manual" ? (step.checklist ?? []) : step.kind === "finalizeUnit" ? (step.confirm ?? []) : [];
  const blocked = run.blockingObligations;
  const done = checklistDone(points, pack, state, ticked);
  const constraints = step.kind === "manual" ? constraintLines(pack, state, step.constrainedBy) : [];
  const unit = pack.vocabulary.unit.one.toLowerCase();
  const label = (step.kind === "manual" || step.kind === "finalizeUnit" ? step.label : undefined) ?? pack.vocabulary.finalize;
  return (
    <PipSection title={label}>
      {constraints.length > 0 && <Constraints lines={constraints} />}
      {blocked.length > 0 && <p className="muted small">Settle what is owed first.</p>}
      {points.length > 0 && <Checklist items={points} pack={pack} state={state} ticked={ticked} onToggle={tick} />}
      <button
        className="primary big"
        disabled={blocked.length > 0}

